static FlValue* item(FlValue* m,const char* k){return m?fl_value_lookup_string(m,k):nullptr;}
static double number(FlValue* v){if(!v)return 0;return fl_value_get_type(v)==FL_VALUE_TYPE_FLOAT?fl_value_get_float(v):static_cast<double>(fl_value_get_int(v));}
