static FlValue* clone(FlValue* v){if(!v)return fl_value_new_null();switch(fl_value_get_type(v)){case FL_VALUE_TYPE_STRING:return fl_value_new_string(fl_value_get_string(v));case FL_VALUE_TYPE_INT:return fl_value_new_int(fl_value_get_int(v));case FL_VALUE_TYPE_FLOAT:return fl_value_new_float(fl_value_get_float(v));case FL_VALUE_TYPE_BOOL:return fl_value_new_bool(fl_value_get_bool(v));case FL_VALUE_TYPE_LIST:{auto* r=fl_value_new_list();for(size_t i=0;i<fl_value_get_length(v);i++)fl_value_append_take(r,clone(fl_value_get_list_value(v,i)));return r;}case FL_VALUE_TYPE_MAP:{auto* r=fl_value_new_map();for(size_t i=0;i<fl_value_get_length(v);i++)fl_value_set_take(r,clone(fl_value_get_map_key(v,i)),clone(fl_value_get_map_value(v,i)));return r;}default:return fl_value_new_null();}}
